// A 40-line Rust baseline used by Cynapse.

#[derive(Debug, Clone)]
struct Lesson {
    title: String,
    completed: bool,
}

impl Lesson {
    fn new(title: &str) -> Self {
        Self {
            title: title.to_string(),
            completed: false,
        }
    }

    fn complete(&mut self) {
        self.completed = true;
    }
}

fn main() {
    let mut lessons = Vec::new();

    lessons.push(Lesson::new("Variables"));
    lessons.push(Lesson::new("Functions"));
    lessons.push(Lesson::new("Ownership"));

    if let Some(first) = lessons.first_mut() {
        first.complete();
    }

    let completed = lessons
        .iter()
        .filter(|lesson| lesson.completed)
        .count();

    println!("Lessons: {}", lessons.len());
    println!("Completed: {}", completed);
}
